import os
import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

os.environ["CXX"] = "hipcc"

cpp_source = """
#include <torch/extension.h>
#include <hip/hip_runtime.h>

#define BLOCK_SIZE 32

torch::Tensor linear_div_gelu(torch::Tensor input, torch::Tensor weight, torch::Tensor bias, float divisor) {
    // input shape: (batch_size, input_size)
    // weight shape: (output_size, input_size)
    // bias shape: (output_size)
    int batch_size = input.size(0);
    int input_size = input.size(1);
    int output_size = weight.size(0);

    auto options = torch::TensorOptions().dtype(torch::kFloat32).device(torch::kCUDA);
    torch::Tensor output = torch::zeros({batch_size, output_size}, options);

    const dim3 threads(BLOCK_SIZE, BLOCK_SIZE);
    const dim3 blocks((output_size + BLOCK_SIZE - 1) / BLOCK_SIZE, (batch_size + BLOCK_SIZE - 1) / BLOCK_SIZE);

    const float sqrt_2_over_pi = 0.7978845608028654; // sqrt(2/π)
    const float c = 0.044715;

    float* input_ptr = input.data_ptr<float>();
    float* weight_ptr = weight.data_ptr<float>();
    float* bias_ptr = bias.data_ptr<float>();
    float* output_ptr = output.data_ptr<float>();

    hipLaunchKernelGGL(
        linear_div_gelu_kernel, 
        blocks, 
        threads, 
        0, 
        0,
        input_ptr, weight_ptr, bias_ptr, output_ptr,
        batch_size, input_size, output_size, divisor,
        sqrt_2_over_pi, c
    );

    return output;
}
"""

hip_source = """
#include <torch/extension.h>
#include <hip/hip_runtime.h>

#define BLOCK_SIZE 32
#define TILE_SIZE 32

extern "C" __global__ void linear_div_gelu_kernel(
    const float* input,
    const float* weight,
    const float* bias,
    float* output,
    int batch_size,
    int input_size,
    int output_size,
    float divisor,
    float sqrt_2_over_pi,
    float c
) {
    __shared__ float input_tile[TILE_SIZE][TILE_SIZE];
    __shared__ float weight_tile[TILE_SIZE][TILE_SIZE];

    int row = blockIdx.y * blockDim.y + threadIdx.y;
    int col = blockIdx.x * blockDim.x + threadIdx.x;

    if (row < batch_size && col < output_size) {
        float sum = 0.0f;

        // Matrix multiplication: input @ weight^T
        for (int tile_idx = 0; tile_idx < (input_size + TILE_SIZE - 1) / TILE_SIZE; ++tile_idx) {
            // Load input tile
            int input_col = tile_idx * TILE_SIZE + threadIdx.x;
            if (input_col < input_size) {
                input_tile[threadIdx.y][threadIdx.x] = input[row * input_size + input_col];
            } else {
                input_tile[threadIdx.y][threadIdx.x] = 0.0f;
            }

            // Load weight tile (weight needs row-major layout)
            int weight_row = tile_idx * TILE_SIZE + threadIdx.y;
            if (weight_row < input_size) {
                weight_tile[threadIdx.y][threadIdx.x] = weight[col * input_size + weight_row];
            } else {
                weight_tile[threadIdx.y][threadIdx.x] = 0.0f;
            }

            __syncthreads();

            // Compute partial sum
            for (int k = 0; k < TILE_SIZE; ++k) {
                sum += input_tile[threadIdx.y][k] * weight_tile[k][threadIdx.x];
            }

            __syncthreads();
        }

        // Add bias
        sum += bias[col];

        // Divide by divisor
        sum /= divisor;

        // Apply GELU activation: x * 0.5 * (1 + tanh(sqrt(2/π) * (x + 0.044715 * x^3)))
        float x_cubed = sum * sum * sum;
        float tanh_arg = sqrt_2_over_pi * (sum + c * x_cubed);
        float tanh_result = tanh(tanh_arg);
        float gelu_result = sum * 0.5f * (1.0f + tanh_result);

        output[row * output_size + col] = gelu_result;
    }
}
"""

# Compile the fused kernel
linear_div_gelu_op = load_inline(
    name="linear_div_gelu",
    cpp_sources=[cpp_source, hip_source],
    functions=["linear_div_gelu"],
    verbose=True,
    extra_cflags=["-O3"],
    extra_hipcflags=["-O3"],
)


class ModelNew(nn.Module):
    def __init__(self, input_size, output_size, divisor):
        super(ModelNew, self).__init__()
        self.linear = nn.Linear(input_size, output_size)
        self.divisor = divisor
        self.linear_div_gelu_op = linear_div_gelu_op

    def forward(self, x):
        # Get the weight and bias from the linear layer
        weight = self.linear.weight
        bias = self.linear.bias

        # Call the fused kernel
        return self.linear_div_gelu_op.linear_div_gelu(x, weight, bias, self.divisor)


def get_inputs():
    return [torch.rand(1024, 8192)]


def get_init_inputs():
    return [8192, 8192, 10.0]

import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline
import os

os.environ["CXX"] = "hipcc"

cpp_source = """
#include <hip/hip_runtime.h>
#include <torch/extension.h>

#define MAX_CHANNELS 64

__global__ void fused_conv3d_softmax_maxpool_kernel(
    const float* input, const float* weight, const float* bias,
    float* output,
    int batch_size, int in_channels, int out_channels,
    int in_depth, int in_height, int in_width,
    int out_depth, int out_height, int out_width,
    int ksize, int pool_ksize, int stride, int pad)
{
    // Block dimensions: (out_channels, 1, 1)
    // Grid dimensions: (out_width, out_height, out_depth * batch_size)

    int out_c = blockIdx.x;
    int ow = threadIdx.x;
    int oh = threadIdx.y;
    int od = threadIdx.z;

    int spatial_offset = blockIdx.y * blockDim.y * blockDim.z + 
                        blockIdx.z * blockDim.z + od;
    int batch_idx = spatial_offset / out_depth;
    int od_global = spatial_offset % out_depth;

    if (batch_idx >= batch_size || out_c >= out_channels || 
        ow >= out_width || oh >= out_height || od >= out_depth) return;

    // Compute conv3d
    float sum = 0.0f;
    for (int ic = 0; ic < in_channels; ++ic) {
        for (int kd = 0; kd < ksize; ++kd) {
            for (int kh = 0; kh < ksize; ++kh) {
                for (int kw = 0; kw < ksize; ++kw) {
                    int id = od_global * stride + kd - pad;
                    int ih = oh * stride + kh - pad;
                    int iw = ow * stride + kw - pad;

                    if (id >= 0 && id < in_depth && 
                        ih >= 0 && ih < in_height && 
                        iw >= 0 && iw < in_width) {
                        int input_idx = ((batch_idx * in_channels + ic) * in_depth + id) * 
                                      in_height * in_width + ih * in_width + iw;
                        int weight_idx = ((out_c * in_channels + ic) * ksize + kd) * 
                                       ksize * ksize + kh * ksize + kw;
                        sum += input[input_idx] * weight[weight_idx];
                    }
                }
            }
        }
    }

    // Add bias
    if (bias != nullptr) {
        sum += bias[out_c];
    }

    // Store conv result in shared memory for softmax
    __shared__ float conv_results[MAX_CHANNELS][8][8][8];
    conv_results[out_c][od][oh][ow] = sum;
    __syncthreads();

    // Softmax: compute max for numerical stability
    if (threadIdx.x == 0 && threadIdx.y == 0 && threadIdx.z == 0) {
        for (int y = 0; y < out_height; ++y) {
            for (int x = 0; x < out_width; ++x) {
                for (int d = 0; d < out_depth; ++d) {
                    float max_val = -1e20f;
                    for (int c = 0; c < out_channels; ++c) {
                        max_val = fmaxf(max_val, conv_results[c][d][y][x]);
                    }

                    // Compute exp and sum
                    float exp_sum = 0.0f;
                    for (int c = 0; c < out_channels; ++c) {
                        float exp_val = expf(conv_results[c][d][y][x] - max_val);
                        conv_results[c][d][y][x] = exp_val;
                        exp_sum += exp_val;
                    }

                    // Normalize
                    for (int c = 0; c < out_channels; ++c) {
                        conv_results[c][d][y][x] /= exp_sum;
                    }
                }
            }
        }
    }
    __syncthreads();

    // Apply max pooling twice (effectively pool size 4)
    // First max pooling
    __shared__ float pool1_results[MAX_CHANNELS][4][4][4];
    int pool1_od = od / 2;
    int pool1_oh = oh / 2;
    int pool1_ow = ow / 2;

    if (od % 2 == 0 && oh % 2 == 0 && ow % 2 == 0) {
        float max_val = -1e20f;
        for (int pd = 0; pd < 2 && od + pd < out_depth; ++pd) {
            for (int ph = 0; ph < 2 && oh + ph < out_height; ++ph) {
                for (int pw = 0; pw < 2 && ow + pw < out_width; ++pw) {
                    max_val = fmaxf(max_val, conv_results[out_c][od + pd][oh + ph][ow + pw]);
                }
            }
        }
        pool1_results[out_c][pool1_od][pool1_oh][pool1_ow] = max_val;
    }
    __syncthreads();

    // Second max pooling
    if (od % 4 == 0 && oh % 4 == 0 && ow % 4 == 0) {
        int pool2_od = od / 4;
        int pool2_oh = oh / 4;
        int pool2_ow = ow / 4;
        int pool1_depth = (out_depth + 1) / 2;
        int pool1_height = (out_height + 1) / 2;
        int pool1_width = (out_width + 1) / 2;

        if (pool2_od < 8 && pool2_oh < 8 && pool2_ow < 8) {
            float max_val = -1e20f;
            for (int pd = 0; pd < 2 && pool1_od + pd < pool1_depth; ++pd) {
                for (int ph = 0; ph < 2 && pool1_oh + ph < pool1_height; ++ph) {
                    for (int pw = 0; pw < 2 && pool1_ow + pw < pool1_width; ++pw) {
                        max_val = fmaxf(max_val, 
                            pool1_results[out_c][pool1_od + pd][pool1_oh + ph][pool1_ow + pw]);
                    }
                }
            }

            int final_od = pool2_od;
            int final_oh = pool2_oh;
            int final_ow = pool2_ow;
            int final_depth = (out_depth + 3) / 4;
            int final_height = (out_height + 3) / 4;
            int final_width = (out_width + 3) / 4;

            if (final_od < final_depth && final_oh < final_height && final_ow < final_width) {
                int output_idx = ((batch_idx * out_channels + out_c) * final_depth + final_od) * 
                               final_height * final_width + final_oh * final_width + final_ow;
                output[output_idx] = max_val;
            }
        }
    }
}

torch::Tensor fused_conv3d_softmax_maxpool(
    torch::Tensor input, torch::Tensor weight, torch::Tensor bias) {

    int batch_size = input.size(0);
    int in_channels = input.size(1);
    int in_depth = input.size(2);
    int in_height = input.size(3);
    int in_width = input.size(4);

    int out_channels = weight.size(0);
    int ksize = weight.size(2);
    int stride = 1;
    int pad = 0;

    int out_depth = in_depth - ksize + 1;
    int out_height = in_height - ksize + 1;
    int out_width = in_width - ksize + 1;

    int pool_ksize = 2;
    int final_depth = (out_depth + 3) / 4;
    int final_height = (out_height + 3) / 4;
    int final_width = (out_width + 3) / 4;

    auto output = torch::zeros({batch_size, out_channels, final_depth, final_height, final_width},
                              input.options());

    dim3 threads(8, 8, 8);
    dim3 blocks(out_channels, (out_height + 7) / 8, (out_depth * batch_size + 7) / 8);

    fused_conv3d_softmax_maxpool_kernel<<<blocks, threads>>>(
        input.data_ptr<float>(), weight.data_ptr<float>(), 
        bias.defined() ? bias.data_ptr<float>() : nullptr,
        output.data_ptr<float>(),
        batch_size, in_channels, out_channels,
        in_depth, in_height, in_width,
        out_depth, out_height, out_width,
        ksize, pool_ksize, stride, pad);

    return output;
}
"""

fused_conv3d = load_inline(
    name="fused_conv3d",
    cpp_sources=cpp_source,
    functions=["fused_conv3d_softmax_maxpool"],
    extra_cuda_cflags=["-O3"],
    verbose=True
)

class ModelNew(nn.Module):
    def __init__(self, in_channels, out_channels, kernel_size, pool_kernel_size):
        super(ModelNew, self).__init__()
        self.conv = nn.Conv3d(in_channels, out_channels, kernel_size, bias=True)
        self.fused_conv3d = fused_conv3d

        # Initialize weights
        nn.init.kaiming_uniform_(self.conv.weight, mode='fan_out', nonlinearity='relu')
        if self.conv.bias is not None:
            nn.init.zeros_(self.conv.bias)

    def forward(self, x):
        # Fused conv3d + softmax + maxpool
        return self.fused_conv3d.fused_conv3d_softmax_maxpool(x, self.conv.weight, self.conv.bias)

