# Fused kernel: matmul + maxpool + sum + scale
cpp_source = """
#include <hip/hip_runtime.h>
#include <hip/hip_fp16.h>

#define BLOCK_SIZE 256

// Fused kernel: matmul + maxpool + sum + scale
// Performs: output = scale * sum(maxpool(matmul(x, W^T)))
__global__ void fused_matmul_maxpool_sum_scale_kernel(
    const float* __restrict__ x,      // input: (batch_size, in_features)
    const float* __restrict__ W,      // weight: (out_features, in_features)
    const float* __restrict__ bias,   // bias: (out_features,)
    float* __restrict__ output,       // output: (batch_size,)
    const int batch_size,
    const int in_features,
    const int out_features,
    const int kernel_size,            // maxpool kernel size (2)
    const float scale_factor
) {
    int batch_idx = blockIdx.x;
    int tid = threadIdx.x;

    if (batch_idx >= batch_size) return;

    // Each thread block processes one batch element
    // and computes the sum of maxpooled outputs
    __shared__ float shared_sum[BLOCK_SIZE];

    float thread_sum = 0.0f;

    // Process output_features in chunks
    // Each thread processes multiple output elements
    for (int out_idx = tid; out_idx < out_features; out_idx += BLOCK_SIZE) {
        // Compute maxpool over [out_idx*kernel_size, (out_idx+1)*kernel_size)
        // Since kernel_size is small (2), we can unroll this
        float max_val = -INFINITY;

        for (int k = 0; k < kernel_size; k++) {
            int full_out_idx = out_idx * kernel_size + k;
            if (full_out_idx >= out_features) continue;

            // Compute dot product: x[batch_idx, :] @ W[full_out_idx, :]
            float dot = bias ? bias[full_out_idx] : 0.0f;

            // Vectorized dot product - process 4 elements at a time
            int i = 0;
            for (; i < in_features - 3; i += 4) {
                float4 x_vec = *reinterpret_cast<const float4*>(&x[batch_idx * in_features + i]);
                float4 w_vec = *reinterpret_cast<const float4*>(&W[full_out_idx * in_features + i]);

                dot += x_vec.x * w_vec.x;
                dot += x_vec.y * w_vec.y;
                dot += x_vec.z * w_vec.z;
                dot += x_vec.w * w_vec.w;
            }

            // Handle remaining elements
            for (; i < in_features; i++) {
                dot += x[batch_idx * in_features + i] * W[full_out_idx * in_features + i];
            }

            // Apply maxpool
            max_val = fmaxf(max_val, dot);
        }

        // Accumulate to thread sum
        thread_sum += max_val;
    }

    // Reduce within block using shared memory
    shared_sum[tid] = thread_sum;
    __syncthreads();

    // Parallel reduction in shared memory
    for (int s = BLOCK_SIZE / 2; s > 0; s >>= 1) {
        if (tid < s) {
            shared_sum[tid] += shared_sum[tid + s];
        }
        __syncthreads();
    }

    // Write final result for this batch element
    if (tid == 0) {
        output[batch_idx] = shared_sum[0] * scale_factor;
    }
}

torch::Tensor fused_matmul_maxpool_sum_scale(
    torch::Tensor x,
    torch::Tensor W,
    torch::Tensor bias,
    const float scale_factor,
    const int kernel_size
) {
    const int batch_size = x.size(0);
    const int in_features = x.size(1);
    const int out_features = W.size(0);

    // Allocate output tensor of shape (batch_size,)
    auto output = torch::zeros({batch_size}, x.options());

    const dim3 blocks(batch_size);
    const dim3 threads(BLOCK_SIZE);

    fused_matmul_maxpool_sum_scale_kernel<<<blocks, threads>>>(
        x.data_ptr<float>(),
        W.data_ptr<float>(),
        bias.numel() > 0 ? bias.data_ptr<float>() : nullptr,
        output.data_ptr<float>(),
        batch_size,
        in_features,
        out_features,
        kernel_size,
        scale_factor
    );

    return output;
}
"""

fused_op = load_inline(
    name="fused_matmul_maxpool_sum_scale",
    cpp_sources=cpp_source,
    functions=["fused_matmul_maxpool_sum_scale"],
    verbose=True,
)


class ModelNew(nn.Module):
    def __init__(self, in_features, out_features, kernel_size, scale_factor):
        super(ModelNew, self).__init__()
        self.linear = nn.Linear(in_features, out_features)
        self.kernel_size = kernel_size
        self.scale_factor = scale_factor
        self.fused_op = fused_op

        # Initialize with same distribution as reference
        nn.init.uniform_(self.linear.weight, -0.1, 0.1)
        nn.init.uniform_(self.linear.bias, -0.1, 0.1)

    def forward(self, x):
        # Use fused kernel that combines matmul, maxpool, sum, and scale
        return self.fused_op.fused_matmul_maxpool_sum_scale(
            x, 
            self.linear.weight, 
            self.linear.bias,
            self.scale_factor,
            self.kernel_size
        )


def get_inputs():
    return [torch.rand(batch_size, in_features)]


def get_init_inputs():
    return [in_features, out_features, kernel_size, scale_factor]

import torch
