# Fused matmul + Swish + bias kernel using tiling for better memory access
matmul_swish_bias_source = """
#include <hip/hip_runtime.h>
#include <math.h>

#define BLK_M 32
#define BLK_N 32
#define BLK_K 16

__global__ void fused_matmul_swish_bias_kernel(
    const float* __restrict__ x,
    const float* __restrict__ W,
    const float* __restrict__ linear_bias,
    const float* __restrict__ extra_bias,
    float* __restrict__ y,
    int batch_size,
    int in_features,
    int out_features) {

    __shared__ float s_x[BLK_M][BLK_K];
    __shared__ float s_W[BLK_K][BLK_N];

    int row = blockIdx.x * BLK_M + threadIdx.x;
    int col = blockIdx.y * BLK_N + threadIdx.y;
    int tx = threadIdx.x;
    int ty = threadIdx.y;

    float sum = 0.0f;

    // Loop over K dimension (in_features)
    for (int k = 0; k < in_features; k += BLK_K) {
        // Load tile of x: x[row, k + ty]
        if (row < batch_size && k + ty < in_features) {
            s_x[tx][ty] = x[row * in_features + (k + ty)];
        } else {
            s_x[tx][ty] = 0.0f;
        }

        // Load tile of W: W[col, k + tx]
        // W is stored as (out_features, in_features)
        if (col < out_features && k + tx < in_features) {
            s_W[tx][ty] = W[col * in_features + (k + tx)];
        } else {
            s_W[tx][ty] = 0.0f;
        }

        __syncthreads();

        // Compute partial sum
        #pragma unroll
        for (int i = 0; i < BLK_K; i++) {
            sum += s_x[tx][i] * s_W[i][ty];
        }

        __syncthreads();
    }

    if (row < batch_size && col < out_features) {
        // Add linear bias
        sum += linear_bias[col];

        // Swish activation: x * sigmoid(x)
        float sigmoid = 1.0f / (1.0f + expf(-sum));
        float swish = sum * sigmoid;

        // Add extra bias
        float result = swish + extra_bias[col];

        y[row * out_features + col] = result;
    }
}

torch::Tensor fused_matmul_swish_bias_hip(
    torch::Tensor x,
    torch::Tensor W,
    torch::Tensor linear_bias,
    torch::Tensor extra_bias) {

    int batch_size = x.size(0);
    int in_features = x.size(1);
    int out_features = W.size(0);

    auto y = torch::zeros({batch_size, out_features}, x.options());

    dim3 block(BLK_M, BLK_N);
    dim3 grid((batch_size + BLK_M - 1) / BLK_M, 
              (out_features + BLK_N - 1) / BLK_N);

    fused_matmul_swish_bias_kernel<<<grid, block>>>(
        x.data_ptr<float>(),
        W.data_ptr<float>(),
        linear_bias.data_ptr<float>(),
        extra_bias.data_ptr<float>(),
        y.data_ptr<float>(),
        batch_size,
        in_features,
        out_features);

    return y;
}
"""

fused_ops = load_inline(
    name="fused_ops",
    cpp_sources=matmul_swish_bias_source,
    functions=["fused_matmul_swish_bias_hip"],
    verbose=True,
)

class ModelNew(nn.Module):
    def __init__(self, in_features, out_features, num_groups, bias_shape):
        super(ModelNew, self).__init__()
        self.in_features = in_features
        self.out_features = out_features
        self.num_groups = num_groups

        # Initialize weights and biases
        self.weight = nn.Parameter(torch.randn(out_features, in_features))
        self.linear_bias = nn.Parameter(torch.randn(out_features))
        self.bias = nn.Parameter(torch.randn(bias_shape))
        self.group_norm = nn.GroupNorm(num_groups, out_features)

    def forward(self, x):
        # Use fused kernel for matmul + Swish + bias
        x = fused_ops.fused_matmul_swish_bias_hip(x, self.weight, self.linear_bias, self.bias)
        # Apply GroupNorm
        x = self.group_norm(x)
        return x

