import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline
import os

os.environ["CXX"] = "hipcc"

cpp_source = """
#include <hip/hip_runtime.h>
#include <torch/extension.h>

#define MAX_CHANNELS 64

__global__ void fused_conv3d_softmax_maxpool_kernel(
    const float* input, const float* weight, const float* bias,
    float* output,
    int batch_size, int in_channels, int out_channels,
    int in_depth, int in_height, int in_width,
    int out_depth, int out_height, int out_width,
    int ksize, int pool_ksize, int stride, int pad)
{
    // Block dimensions: (out_channels, 1, 1)
    // Grid dimensions: (out_width, out_height, out_depth * batch_size)

    int out_c = blockIdx.x;
    int ow = threadIdx.x;
    int oh = threadIdx.y;
    int od = threadIdx.z;

    int spatial_offset = blockIdx.y * blockDim.y * blockDim.z + 
                        blockIdx.z * blockDim.z + od;
    int batch_idx = spatial_offset / out_depth;
    int od_global = spatial_offset % out_depth;

    if (batch_idx >= batch_size || out_c >= out_channels || 
        ow >= out_width || oh >= out_height || od >= out_depth) return;

    // Compute conv3d
    float sum = 0.0f;
    for (int ic = 0; ic < in_channels; ++ic) {
        for (int kd = 0; kd < ksize; ++kd) {
            for (int kh = 0; kh < ksize; ++kh) {
                for (int kw = 0; kw < ksize; ++kw) {
                    int id = od_global * stride + kd - pad;
                    int ih = oh * stride + kh - pad;
                    int iw = ow * stride + kw - pad;

                    if (id >= 0 && id < in_depth && 
                        ih >= 0 && ih < in_height && 
                        iw >= 0 && iw < in_width) {
                        int input_idx = ((batch_idx * in_channels + ic) * in_depth + id) * 
                                      in_height * in_width + ih * in_width + iw;
                        int weight_idx = ((out_c * in_channels + ic) * ksize + kd) * 
                                       ksize * ksize + kh * ksize + kw;
                        sum += input[input_idx] * weight[weight_idx];
                    }
                }
            }
        }
    }

    // Add bias
    if (bias != nullptr) {
        sum += bias[out_c];
    }

    // Store conv result in shared memory for softmax
    __shared__ float conv_results[MAX_CHANNELS][8][8][8];
    conv_results[out_c][od][oh][ow] = sum;
    __syncthreads();

    // Softmax: compute max for numerical stability
    if (threadIdx.x == 0 && threadIdx.y == 0 && threadIdx.z == 0) {
        for (int y = 0; y < out_height; ++y) {
            for (int x = 0; x < out_width; ++x) {
                for (int d = 0; d < out_depth; ++d) {
                    float max_val = -1e20f;
                    for (int c = 0; c < out_channels; ++c) {
                        max_val = fmaxf(max_val, conv_results[c][d][y][x]);
                    }

                    // Compute exp and sum
                    float exp_sum = 0.0f;
                    for (int c = 0; c < out_channels; ++c) {
                        float exp_val = expf(conv_results[c][d][y][x] - max_val);
                        conv_results[c][d][y][x] = exp_val;
                        exp_sum += exp_val;
                    }

                    // Normalize
                    for (int c = 0; c < out_channels; ++c) {
                        conv_results[c][d][y][x] /= exp_sum;
                    }
                }
            }
        }
    }
    __syncthreads();

    // Apply max pooling twice (effectively pool size 4)
    // First max pooling
    __shared__ float pool1_results[MAX_CHANNELS][4][4][4];
    int pool1_od = od / 2;
    int pool1_oh = oh / 2;
    int pool1_ow = ow / 2;

    if (od % 2 == 0 && oh % 2 == 0 && ow % 2 == 0) {
        float max_val = -1e20f;
        for (int pd = 0; pd < 2 && od + pd < out_depth; ++pd) {
            for (int ph = 0; ph < 2 && oh + ph < out_height; ++ph) {
                for (int pw = 0; pw < 2 && ow + pw < out_width; ++pw) {
                    max_val = fmaxf(max_val, conv_results[out_c][od + pd][oh + ph][ow + pw]);
                }
            }
        }
        pool1_results[out_c][pool1_od][pool1_oh][pool1_ow] = max_val;
    }
    __syncthreads();

    // Second max pooling
    if (od % 4 == 0 && oh % 4 == 0 && ow % 4 == 0) {
        int pool2_od = od / 4;
        int pool2_oh = oh / 4;
        int pool2_ow = ow / 4;
        int pool1_depth = (out_depth + 1) / 2;
        int pool1_height = (out_height + 1) / 2;
        int pool1_width = (out_width + 1) / 2;

        if (pool2_od < 8 && pool2_oh < 8 && pool2_ow < 8) {
            float max_val = -1e20f;
            for (int pd = 0; pd < 2 && pool1_od + pd < pool1_depth; ++pd) {
                for (int ph = 0; ph < 2 && pool1_oh + ph < pool1_height; ++ph) {
                    for (int pw = 0; pw < 2 && pool1_ow + pw < pool1_width; ++pw) {
                        max_val = fmaxf(max_val, 
                            pool1_results[out_c][pool1_od + pd][pool1_oh + ph][pool1_ow + pw]);
                    }
                }
            }

            int final_od = pool2_od;
            int final_oh = pool2_oh;
            int final_ow = pool2_ow;
            int final_depth = (out_depth + 3) / 4;
            int final_height = (out_height + 3) / 4;
            int final_width = (out_width + 3) / 4;

            if (final_od < final_depth && final_oh < final_height && final_ow < final_width) {
                int output_idx = ((batch_idx * out_channels + out_c) * final_depth + final_od) * 
                               final_height * final_width + final_oh * final_width + final_ow;
                output[output_idx] = max_val;
            }
        }
    }
}

torch::Tensor fused_conv3d_softmax_maxpool(
    torch::Tensor input, torch::Tensor weight, torch::Tensor bias) {

    int batch_size = input.size(0);
    int in_channels = input.size(1);
    int in_depth = input.size(2);
    int in_height = input.size(3);
    int in_width = input.size(4);

    int out_channels = weight.size(0);
    int ksize = weight.size(2);
    int stride = 1;
    int pad = 0;

    int out_depth = in_depth - ksize + 1;
    int out_height = in_height - ksize + 1;
    int out_width = in_width - ksize + 1;

    int pool_ksize = 2;
    int final_depth = (out_depth + 3) / 4;
    int final_height = (out_height + 3) / 4;
    int final_width = (out_width + 3) / 4;

    auto output = torch::zeros({batch_size, out_channels, final_depth, final_height, final_width},
                              input.options());

