        # Use custom fused kernel for conv + subtract1 + tanh + subtract2
        x = self.custom_ops.fused_conv_sub_tanh_sub(
            x, weight, bias, self.subtract1_value, self.subtract2_value
        )

        # Use custom avgpool kernel
