# Fused kernel: matmul + maxpool + sum + scale
cpp_source = """
#include <hip/hip_runtime.h>

// Kernel configuration
#define BLOCK_SIZE 256
#define UNROLL_FACTOR 4

// Fused kernel: linear + maxpool + sum + scale
// Performs: output = scale * sum(maxpool(linear(x)))
// Note: maxpool only operates along feature dimension
__global__ void fused_kernel(
    const float* __restrict__ x,      // input: (batch_size, in_features)
    const float* __restrict__ W,      // weight: (out_features, in_features)  
    const float* __restrict__ bias,   // bias: (out_features,)
    float* __restrict__ output,       // output: (batch_size,)
    int batch_size,
    int in_features,
    int out_features,
    int kernel_size,                  // maxpool kernel size (2)
    float scale_factor
) {
    int batch_idx = blockIdx.x;
    int tid = threadIdx.x;

    if (batch_idx >= batch_size) return;

    // Each block processes one batch element
    __shared__ float shared_buffer[BLOCK_SIZE];

    // Process output features in tiles
    // Each thread computes multiple maxpooled outputs
    float thread_total = 0.0f;

    // Loop through output feature pairs (maxpool groups)
    for (int out_tile_start = tid * kernel_size; out_tile_start < out_features; 
         out_tile_start += BLOCK_SIZE * kernel_size) {

        // Process up to kernel_size outputs (for maxpool)
        for (int k = 0; k < kernel_size; k++) {
            int out_idx = out_tile_start + k;
            if (out_idx >= out_features) continue;

            // Compute dot product: x[batch_idx, :] @ W[out_idx, :]
            float dot_val = (bias != nullptr) ? bias[out_idx] : 0.0f;

            // Vectorized dot product - process 4 elements at a time
            int i = 0;
            for (; i < in_features - 3; i += 4) {
                float4 x_vec = *reinterpret_cast<const float4*>(&x[batch_idx * in_features + i]);
                float4 w_vec = *reinterpret_cast<const float4*>(&W[out_idx * in_features + i]);

                dot_val += x_vec.x * w_vec.x;
                dot_val += x_vec.y * w_vec.y;
                dot_val += x_vec.z * w_vec.z;
                dot_val += x_vec.w * w_vec.w;
            }

            // Handle remaining elements
            for (; i < in_features; i++) {
                dot_val += x[batch_idx * in_features + i] * W[out_idx * in_features + i];
            }

            // For maxpool: take max over kernel_size adjacent features
            if (k == 0) {
                // Store first value for this maxpool group
                shared_buffer[tid] = dot_val;
            } else {
                // Update max value for this maxpool group
                shared_buffer[tid] = fmaxf(shared_buffer[tid], dot_val);
            }
        }

        // Accumulate the max value from this group
        thread_total += shared_buffer[tid];
    }

    // Global reduction for this batch element
    shared_buffer[tid] = thread_total;
    __syncthreads();

    // Parallel reduction in shared memory
    for (int s = BLOCK_SIZE / 2; s > 0; s >>= 1) {
        if (tid < s) {
            shared_buffer[tid] += shared_buffer[tid + s];
        }
        __syncthreads();
    }

    // Write final result for this batch 
    if (tid == 0) {
        output[batch_idx] = shared_buffer[0] * scale_factor;
    }
}

torch::Tensor fused_forward(
    torch::Tensor x,      // (batch_size, in_features)
    torch::Tensor W,      // (out_features, in_features)
    torch::Tensor bias,   // (out_features,)
    float scale_factor,
    int kernel_size
) {
    int batch_size = x.size(0);
    int in_features = x.size(1);
    int out_features = W.size(0);

    // Allocate output tensor (batch_size,)
    auto output = torch::zeros({batch_size}, x.options());

    dim3 blocks(batch_size);
    dim3 threads(BLOCK_SIZE);

    fused_kernel<<<blocks, threads>>>(
        x.data_ptr<float>(),
        W.data_ptr<float>(),
        bias.numel() > 0 ? bias.data_ptr<float>() : nullptr,
        output.data_ptr<float>(),
        batch_size,
        in_features,
        out_features,
        kernel_size,
        scale_factor
    );

    return output;
}
"""

