#include <hip/hip_runtime.h>

#define BLOCK_SIZE 256

// Fused kernel: linear + maxpool + sum + scale
__global__ void fused_kernel(
    const float* __restrict__ x,      // input: (batch_size, in_features)
    const float* __restrict__ W,      // weight: (out_features, in_features)
    const float* __restrict__ bias,   // bias: (out_features,)
    float* __restrict__ output,       // output: (batch_size,)
    int batch_size,
    int in_features,
    int out_features,
    int kernel_size,                  // maxpool kernel size (2)
    float scale_factor
) {
    // Each block processes one batch element
    __shared__ float shared_sum[BLOCK_SIZE];

    int batch_idx = blockIdx.x;
    int tid = threadIdx.x;

    if (batch_idx >= batch_size) return;

    float thread_result = 0.0f;

    // Process output features in tiles
    // Each thread computes the maxpooled result for a region
    for (int out_start = tid * kernel_size; out_start < out_features; 
         out_start += BLOCK_SIZE * kernel_size) {

        float max_val = -1e30f;  // Very small number for max initialization

        // Process maxpool group [out_start, out_start + kernel_size)
        for (int k = 0; k < kernel_size && (out_start + k) < out_features; k++) {
            int out_idx = out_start + k;

            // Compute linear transformation: out = W @ x + bias[out_idx]
            float dot = 0.0f;

            // Add bias if present
            if (bias != nullptr) {
                dot = bias[out_idx];
            }

            // Vectorized matmul: process 4 elements at a time
            int i = 0;
            for (; i <= in_features - 4; i += 4) {
                float4 x_val = *reinterpret_cast<const float4*>(&x[batch_idx * in_features + i]);
                float4 w_val = *reinterpret_cast<const float4*>(&W[out_idx * in_features + i]);

                dot += x_val.x * w_val.x;
                dot += x_val.y * w_val.y;
                dot += x_val.z * w_val.z;
                dot += x_val.w * w_val.w;
            }

            // Handle remaining elements
            for (; i < in_features; i++) {
                dot += x[batch_idx * in_features + i] * W[out_idx * in_features + i];
            }

            // Update maxpool (take maximum in the group)
            max_val = fmaxf(max_val, dot);
        }

        // Accumulate the max value for this group
        // Only accumulate if we processed this group
        if (out_start < out_features) {
            thread_result += max_val;
        }
    }

    // Store thread contribution to shared memory
    shared_sum[tid] = thread_result;
    __syncthreads();

    // Parallel reduction in shared memory
    for (int s = BLOCK_SIZE / 2; s > 0; s >>= 1) {
        if (tid < s) {
            shared_sum[tid] += shared_sum[tid + s];
        }
        __syncthreads();
    }

    // Final result: write scaled sum for this batch element
    if (tid == 0) {
        output[batch_idx] = shared_sum[0] * scale_factor;
    }
}

