gelu_cpp = """
#include <hip/hip_runtime.h>

__device__ float gelu_activation(float x) {
    const float sqrt_2_over_pi = 0.7978845608f;
    const float coeff = 0.044715f;
    return 0.5f * x * (1.0f + tanhf(sqrt_2_over_pi * (x + coeff * x * x * x)));
}

__global__ void gelu_kernel(float* __restrict__ x, int size) {
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    if (idx < size) {
        x[idx] = gelu_activation(x[idx]);
    }
}

torch::Tensor gelu(torch::Tensor x) {
    int size = x.numel();
    const int block_size = 256;
    const int num_blocks = (size + block_size - 1) / block_size;

    gelu_kernel<<<num_blocks, block_size>>>(x.data_ptr<float>(), size);
    return x;
}
"""

# Optimized Softmax kernel using online algorithm
softmax_cpp = """
#include <hip/hip_runtime.h>
#include <math.h>

__global__ void softmax_kernel(const float* __restrict__ input, float* __restrict__ output, int rows, int cols) {
    int row = blockIdx.x * blockDim.x + threadIdx.x;

    if (row >= rows) return;

    const float* row_input = input + row * cols;
    float* row_output = output + row * cols;

    // Online softmax - compute max for numerical stability
    float max_val = -INFINITY;
    for (int i = 0; i < cols; i++) {
        max_val = fmaxf(max_val, row_input[i]);
    }

    // Compute sum of exp(x - max)
    float sum_exp = 0.0f;
    for (int i = 0; i < cols; i++) {
        sum_exp += expf(row_input[i] - max_val);
    }

    // Compute final softmax
    float inv_sum = 1.0f / sum_exp;
    for (int i = 0; i < cols; i++) {
        row_output[i] = expf(row_input[i] - max_val) * inv_sum;
    }
}

torch::Tensor softmax(torch::Tensor input) {
    int rows = input.size(0);
    int cols = input.size(1);

    auto output = torch::empty_like(input);

    const int block_size = 256;
    const int num_blocks = (rows + block_size - 1) / block_size;

    softmax_kernel<<<num_blocks, block_size>>>(
        input.data_ptr<float>(), output.data_ptr<float>(), rows, cols);

    return output;
}
"""

