#define EPSILON 1e-5f

// Fused Conv2D + BatchNorm + Scaling kernel
__global__ void fused_conv_bn_scale_kernel(
    const float* __restrict__ input, 
    const float* __restrict__ weight, 
    const float* __restrict__ bias,
    const float* __restrict__ bn_mean, 
    const float* __restrict__ bn_var, 
    const float* __restrict__ bn_weight, 
    const float* __restrict__ bn_bias,
    float* __restrict__ output,
    int N, int C_in, int H, int W,
    int C_out, int K_h, int K_w,
    int H_out, int W_out,
    float scaling_factor
) {
    int idx = blockIdx.x * blockDim.x + threadIdx.x;

    // Decompose index into n, c_out, h_out, w_out
    int n = idx / (C_out * H_out * W_out);
    if (n >= N) return;

    int tmp = idx % (C_out * H_out * W_out);
    int c_out = tmp / (H_out * W_out);
    tmp = tmp % (H_out * W_out);
    int h_out = tmp / W_out;
    int w_out = tmp % W_out;

    // Check bounds
    if (c_out >= C_out || h_out >= H_out || w_out >= W_out) return;

    // Precompute BN + scale parameters
    float inv_std = rsqrtf(bn_var[c_out] + EPSILON);
    float bn_scale = bn_weight[c_out] * scaling_factor * inv_std;
    float bn_bias_val = bn_bias[c_out] * scaling_factor - bn_mean[c_out] * bn_weight[c_out] * scaling_factor * inv_std;

    // Add conv bias if it exists
    if (bias != nullptr) {
        bn_bias_val += bias[c_out] * bn_scale;
    }

    // Compute convolution
    float sum = 0.0f;

    // Loop over input channels (C_in = 8)
    #pragma unroll
    for (int c_in = 0; c_in < C_in; ++c_in) {
        // Calculate base pointers for this channel
        const float* input_channel = input + (n * C_in + c_in) * H * W;
        const float* weight_channel = weight + (c_out * C_in + c_in) * K_h * K_w;

        // Loop over kernel (3x3)
        #pragma unroll
        for (int kh = 0; kh < K_h; ++kh) {
            #pragma unroll
            for (int kw = 0; kw < K_w; ++kw) {
                int h_in = h_out + kh;
                int w_in = w_out + kw;

                // Load input value (coalesced access within a warp)
                float input_val = input_channel[h_in * W + w_in];

                // Load weight value
                float weight_val = weight_channel[kh * K_w + kw];

                sum += input_val * weight_val;
            }
        }
    }

    // Apply fused BN + scale
    float result = sum * bn_scale + bn_bias_val;

    // Store output (coalesced access within a warp)
    output[((n * C_out + c_out) * H_out + h_out) * W_out + w_out] = result;
}

