#include <hip/hip_runtime.h>
#include <math.h>

#define TILE_SIZE 16

__global__ void fused_matmul_swish_bias_kernel(
    const float* __restrict__ x,
    const float* __restrict__ W,
    const float* __restrict__ linear_bias,
    const float* __restrict__ extra_bias,
    float* __restrict__ y,
    int batch_size,
    int in_features,
    int out_features) {

    __shared__ float s_x[TILE_SIZE][TILE_SIZE];
    __shared__ float s_W[TILE_SIZE][TILE_SIZE];

    int row = blockIdx.y * TILE_SIZE + threadIdx.y;
    int col = blockIdx.x * TILE_SIZE + threadIdx.x;
    int tx = threadIdx.x;
    int ty = threadIdx.y;

    float sum = 0.0f;

    // Loop over K dimension (in_features)
    for (int k = 0; k < in_features; k += TILE_SIZE) {
        // Load tile of x: x[row, k + tx]
        if (row < batch_size && k + tx < in_features) {
            s_x[ty][tx] = x[row * in_features + (k + tx)];
        } else {
            s_x[ty][tx] = 0.0f;
        }

        // Load tile of W: W[col, k + ty]
        // W is stored as (out_features, in_features) - row-major
        if (col < out_features && k + ty < in_features) {
            s_W[ty][tx] = W[col * in_features + (k + ty)];
        } else {
            s_W[ty][tx] = 0.0f;
        }

        __syncthreads();

        // Compute partial sum
        #pragma unroll
        for (int i = 0; i < TILE_SIZE; i++) {
            sum += s_x[ty][i] * s_W[i][tx];
        }

        __syncthreads();
    }

    if (row < batch_size && col < out_features) {
        // Add linear bias from nn.Linear
        sum += linear_bias[col];

        // Swish activation: x * sigmoid(x)
        // Use fast approximation for sigmoid to avoid potential issues
        float exp_val = expf(-fabsf(sum));
        float sigmoid = (sum >= 0.0f) ? (1.0f / (1.0f + exp_val)) : (exp_val / (1.0f + exp_val));
        float swish = sum * sigmoid;

        // Add extra bias parameter
        y[row * out_features + col] = swish + extra_bias[col];
    }
}

