        float act_output = tanh_val * sum;

        // Apply batchnorm
        int output_idx = ((b * out_channels + oc) * out_height + oh) * out_width + ow;
        output[output_idx] = act_output * bn_scale[oc] + bn_bias[oc];
    }
}

// Simple version with better parallelism
__global__ void fused_conv_activation_bn_kernel_simple(
    const float* input, const float* weight, const float* bias,
    const float* bn_scale, const float* bn_bias,
    float* output,
    int batch_size, int in_channels, int out_channels,
    int in_height, int in_width, int out_height, int out_width, int kernel_size
) {
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    int total_elements = batch_size * out_channels * out_height * out_width;

    if (idx >= total_elements) return;

    // NCHW layout
    int tmp = idx;
    int w = tmp % out_width;
    tmp /= out_width;
    int h = tmp % out_height;
    tmp /= out_height;
    int c = tmp % out_channels;
    int n = tmp / out_channels;

    // Compute convolution
    float sum = bias[c];

    // Unroll loops for better performance
    #pragma unroll 4
    for (int ic = 0; ic < in_channels; ic++) {
        int input_offset = ((n * in_channels + ic) * in_height + h) * in_width;
        int weight_offset = ((c * in_channels + ic) * kernel_size);

        #pragma unroll 3
        for (int kh = 0; kh < kernel_size; kh++) {
            #pragma unroll 3
            for (int kw = 0; kw < kernel_size; kw++) {
                int ih = h + kh;
                int iw = w + kw;
                sum += input[input_offset + ih * in_width + iw] * 
                       weight[weight_offset + kh * kernel_size + kw];
            }
        }
    }

    // Apply activation: tanh(softplus(x)) * x
    float softplus = logf(1.0f + expf(sum));
    float tanh_val = tanhf(softplus);
    float act_output = tanh_val * sum;

    // Apply batchnorm
    output[idx] = act_output * bn_scale[c] + bn_bias[c];
}

torch::Tensor fused_conv_bn_hip(
    torch::Tensor input, torch::Tensor weight, torch::Tensor bias,
    torch::Tensor bn_scale, torch::Tensor bn_bias
) {
    int batch_size = input.size(0);
    int in_channels = input.size(1);
    int in_height = input.size(2);
    int in_width = input.size(3);

    int out_channels = weight.size(0);
    int kernel_size = weight.size(2);

    // Calculate output dimensions
    int out_height = in_height - kernel_size + 1;
    int out_width = in_width - kernel_size + 1;

    auto output = torch::empty({batch_size, out_channels, out_height, out_width}, input.options());

    int total_elements = batch_size * out_channels * out_height * out_width;

    // More optimal thread configuration
    const int threads_per_block = 256;
    const int blocks_per_grid = (total_elements + threads_per_block - 1) / threads_per_block;

    fused_conv_activation_bn_kernel_simple<<<blocks_per_grid, threads_per_block>>>(
        input.data_ptr<float>(),
        weight.data_ptr<float>(),
        bias.data_ptr<float>(),
        bn_scale.data_ptr<float>(),
        bn_bias.data_ptr<float>(),
        output.data_ptr<float>(),
        batch_size, in_channels, out_channels,
        in_height, in_width, out_height, out_width, kernel_size
    );

    return output;
}
"""

