# Fused HIP kernel for GEMM + Swish + Scaling
fused_kernel_cpp_source = """
#include <hip/hip_runtime.h>

#define BLOCK_SIZE_M 64
#define BLOCK_SIZE_N 64
#define BLOCK_SIZE_K 8
#define THREAD_SIZE_M 4
#define THREAD_SIZE_N 4

__global__ void fused_gemm_swish_scale_kernel(
    const float* __restrict__ A,
    const float* __restrict__ B,
    const float* __restrict__ bias,
    float* __restrict__ C,
    int M, int N, int K, float scaling_factor) {

    int bx = blockIdx.x;
    int by = blockIdx.y;
    int tx = threadIdx.x;
    int ty = threadIdx.y;

    __shared__ float As[BLOCK_SIZE_M][BLOCK_SIZE_K];
    __shared__ float Bs[BLOCK_SIZE_K][BLOCK_SIZE_N];

    float C_local[THREAD_SIZE_M][THREAD_SIZE_N];
    for (int i = 0; i < THREAD_SIZE_M; i++) {
        for (int j = 0; j < THREAD_SIZE_N; j++) {
            C_local[i][j] = 0.0f;
        }
    }

    for (int tile = 0; tile < (K + BLOCK_SIZE_K - 1) / BLOCK_SIZE_K; ++tile) {
        // Load tile from A
        for (int i = 0; i < BLOCK_SIZE_M; i += blockDim.y) {
            int row = by * BLOCK_SIZE_M + ty + i;
            int col = tile * BLOCK_SIZE_K + tx;
            if (row < M && col < K) {
                As[ty + i][tx] = A[row * K + col];
            } else {
                As[ty + i][tx] = 0.0f;
            }
        }

        // Load tile from B (weight.t())
        for (int i = 0; i < BLOCK_SIZE_N; i += blockDim.x) {
            int row = tile * BLOCK_SIZE_K + ty;
            int col = bx * BLOCK_SIZE_N + tx + i;
            if (row < K && col < N) {
                Bs[ty][tx + i] = B[col * K + row];
            } else {
                Bs[ty][tx + i] = 0.0f;
            }
        }

        __syncthreads();

        // Compute tile
        for (int k = 0; k < BLOCK_SIZE_K; k++) {
            #pragma unroll
            for (int i = 0; i < THREAD_SIZE_M; i++) {
                #pragma unroll
                for (int j = 0; j < THREAD_SIZE_N; j++) {
                    int row = ty * THREAD_SIZE_M + i;
                    int col = tx * THREAD_SIZE_N + j;
                    C_local[i][j] += As[row][k] * Bs[k][col];
                }
            }
        }

        __syncthreads();
    }

    // Store results
    for (int i = 0; i < THREAD_SIZE_M; i++) {
        for (int j = 0; j < THREAD_SIZE_N; j++) {
            int row = by * BLOCK_SIZE_M + ty * THREAD_SIZE_M + i;
            int col = bx * BLOCK_SIZE_N + tx * THREAD_SIZE_N + j;
            if (row < M && col < N) {
                float value = C_local[i][j];
                value += bias[col];
                float sigmoid = 1.0f / (1.0f + expf(-value));
                value = value * sigmoid * scaling_factor;
                C[row * N + col] = value;
            }
        }
    }
}

torch::Tensor fused_gemm_swish_scale_hip(
    torch::Tensor A,
    torch::Tensor B,
    torch::Tensor bias,
    float scaling_factor) {

    int M = A.size(0);
    int K = A.size(1);
    int N = B.size(0);

    auto C = torch::zeros({M, N}, torch::dtype(torch::kFloat32).device(A.device()));

    dim3 blockDim(BLOCK_SIZE_N / THREAD_SIZE_N, BLOCK_SIZE_M / THREAD_SIZE_M);
    dim3 gridDim((N + BLOCK_SIZE_N - 1) / BLOCK_SIZE_N, 
                 (M + BLOCK_SIZE_M - 1) / BLOCK_SIZE_M);

    fused_gemm_swish_scale_kernel<<<gridDim, blockDim>>>(
        A.data_ptr<float>(),
        B.data_ptr<float>(),
        bias.numel() > 0 ? bias.data_ptr<float>() : nullptr,
        C.data_ptr<float>(),
        M, N, K, scaling_factor);

    return C;
}
"""

