class ModelNew(nn.Module):
    def __init__(self, in_channels, out_channels, kernel_size, eps=1e-5, momentum=0.1):
        super(ModelNew, self).__init__()
        self.conv = nn.Conv2d(in_channels, out_channels, kernel_size)
        self.bn = nn.BatchNorm2d(out_channels, eps=eps, momentum=momentum)
        self.fused_conv_bn = fused_conv_bn

    def forward(self, x):
        # Precompute batchnorm scale and bias for inference
        bn_scale = self.bn.weight / torch.sqrt(self.bn.running_var + self.bn.eps)
        bn_bias = self.bn.bias - self.bn.running_mean * bn_scale

        # Ensure contiguous and float32
        x = x.contiguous().float()
        weight = self.conv.weight.contiguous().float()
        bias = self.conv.bias.contiguous().float()
        bn_scale = bn_scale.contiguous().float()
        bn_bias = bn_bias.contiguous().float()

        return self.fused_conv_bn.fused_conv_bn_hip(x, weight, bias, bn_scale, bn_bias)

