matmul_swish_bias_source = """
#include <hip/hip_runtime.h>
#include <math.h>

#define BLOCK_SIZE 256

__global__ void fused_matmul_swish_bias_kernel(
    const float* __restrict__ x,
    const float* __restrict__ weight,
    const float* __restrict__ linear_bias,
    const float* __restrict__ extra_bias,
    float* __restrict__ output,
    int batch_size,
    int in_features,
    int out_features) {

    int tid = threadIdx.x;
    int row = blockIdx.x;

    if (row >= batch_size) return;

    // Each thread processes one output element
    // Row-based parallelization: each thread handles a subset of columns
    int cols_per_thread = (out_features + BLOCK_SIZE - 1) / BLOCK_SIZE;

    for (int t = 0; t < cols_per_thread; t++) {
        int col = t * BLOCK_SIZE + tid;
        if (col < out_features) {
            float sum = 0.0f;

            // Compute dot product: x[row] @ weight[col]
            for (int i = 0; i < in_features; i++) {
                sum += x[row * in_features + i] * weight[col * in_features + i];
            }

            // Add linear bias
            sum += linear_bias[col];

            // Swish activation: x * sigmoid(x)
            float sigmoid = 1.0f / (1.0f + expf(-sum));
            float swish = sum * sigmoid;

            // Add extra bias
            float result = swish + extra_bias[col];

            output[row * out_features + col] = result;
        }
    }
}

torch::Tensor fused_matmul_swish_bias_hip(
    torch::Tensor x,
    torch::Tensor weight,
    torch::Tensor linear_bias,
    torch::Tensor extra_bias) {

    int batch_size = x.size(0);
    int in_features = x.size(1);
    int out_features = weight.size(0);

    auto output = torch::zeros({batch_size, out_features}, x.options());

    dim3 block(BLOCK_SIZE);
    dim3 grid(batch_size);

    fused_matmul_swish_bias_kernel<<<grid, block>>>(
        x.data_ptr<float>(),
        weight.data_ptr<float>(),
        linear_bias.data_ptr<float>(),
        extra_bias.data_ptr<float>(),
        output.data_ptr<float>(),
        batch_size,
        in_features,
        out_features);

    return output;
}
"""

