matmul_scaling_residual_cpp_source = """
#include <hip/hip_runtime.h>

__global__ void matmul_scaling_residual_kernel(
    const float* __restrict__ A,
    const float* __restrict__ B,
    const float* __restrict__ bias,
    float* __restrict__ C,
    int M,
    int N,
    int K,
    float scaling_factor) {

    // Matrix dimensions:
    // A: M x K (input)
    // B: K x N (weight transposed)
    // bias: N (bias vector)
    // C: M x N (output)

    int row = blockIdx.y * blockDim.y + threadIdx.y;
    int col = blockIdx.x * blockDim.x + threadIdx.x;

    if (row < M && col < N) {
        float sum = 0.0f;

        // Compute dot product for this output element
        // A: M x K, B^T: K x N, so access A[row * K + k] and B[col + k * N]
        for (int k = 0; k < K; k++) {
            sum += A[row * K + k] * B[k * N + col];
        }

        // Add bias
        sum += bias[col];

        // Apply scaling and add residual (original matmul+bias result)
        // result = sum * scaling_factor + sum = sum * (1.0 + scaling_factor)
        C[row * N + col] = sum * (1.0f + scaling_factor);
    }
}

torch::Tensor matmul_scaling_residual_hip(
    torch::Tensor A,
    torch::Tensor B,
    torch::Tensor bias,
    float scaling_factor) {

    int M = A.size(0);
    int K = A.size(1);
    int N = B.size(0);

    auto C = torch::zeros({M, N}, A.options());

    dim3 block_size(32, 32);
    dim3 num_blocks((N + block_size.x - 1) / block_size.x,
                    (M + block_size.y - 1) / block_size.y);

    hipLaunchKernelGGL(
        matmul_scaling_residual_kernel,
        num_blocks,
        block_size,
        0,
        0,
        A.data_ptr<float>(),
        B.data_ptr<float>(),
        bias.data_ptr<float>(),
        C.data_ptr<float>(),
        M,
        N,
        K,
        scaling_factor
    );

    return C;
}
"""

