# Simpler and more readable HIP kernel for GEMM + Swish + Scaling
fused_kernel_cpp_source = """
#include <hip/hip_runtime.h>

#define BLOCK_SIZE_X 256
#define BLOCK_SIZE_Y 1

template<int BLOCK_X, int BLOCK_Y>
__global__ void fused_gemm_swish_scale_kernel(
    const float* __restrict__ A,      // input: [M, K]
    const float* __restrict__ B,      // weight: [N, K] (stored as weight.t())
    const float* __restrict__ bias,   // bias: [N]
    float* __restrict__ C,            // output: [M, N]
    int M, int N, int K, float scaling_factor) {

    int row = blockIdx.y * BLOCK_Y + threadIdx.y;
    int col_start = blockIdx.x * BLOCK_X + threadIdx.x;

    if (row >= M) return;

    float value = 0.0f;

    // Compute dot product: output[row][col] = sum(A[row][k] * B[col][k])
    // where A is [M, K] and B is [N, K]
    for (int k = 0; k < K; k++) {
        value += A[row * K + k] * B[col_start * K + k];
    }

    // Add bias
    if (bias != nullptr) {
        value += bias[col_start];
    }

    // Apply Swish activation: x * sigmoid(x)
    float sigmoid = 1.0f / (1.0f + expf(-value));
    value = value * sigmoid * scaling_factor;

    if (row < M && col_start < N) {
        C[row * N + col_start] = value;
    }
}

torch::Tensor fused_gemm_swish_scale_hip(
    torch::Tensor A,
    torch::Tensor B,
    torch::Tensor bias,
    float scaling_factor) {

    int M = A.size(0);
    int K = A.size(1);
    int N = B.size(0);

    auto C = torch::zeros({M, N}, torch::dtype(torch::kFloat32).device(A.device()));

    dim3 blockDim(BLOCK_SIZE_X, BLOCK_SIZE_Y);
    dim3 gridDim((N + BLOCK_SIZE_X - 1) / BLOCK_SIZE_X, 
                 (M + BLOCK_SIZE_Y - 1) / BLOCK_SIZE_Y);

    fused_gemm_swish_scale_kernel<BLOCK_SIZE_X, BLOCK_SIZE_Y><<<gridDim, blockDim>>>(
        A.data_ptr<float>(),
        B.data_ptr<float>(),
        bias.numel() > 0 ? bias.data_ptr<float>() : nullptr,
        C.data_ptr<float>(),
        M, N, K, scaling_factor);

    return C;
}
"""

