# Optimized fused kernel with tiling for better memory access
matmul_swish_bias_source = """
#include <hip/hip_runtime.h>
#include <hip/hip_fp16.h>
#include <math.h>

#define TILE_SIZE 32
#define BLOCK_SIZE_Y 8
#define BLOCK_SIZE_X 32

__global__ void fused_matmul_swish_bias_kernel(
    const float* __restrict__ x,
    const float* __restrict__ weight,
    const float* __restrict__ linear_bias,
    const float* __restrict__ extra_bias,
    float* __restrict__ output,
    int batch_size,
    int in_features,
    int out_features) {

    __shared__ float s_x[BLOCK_SIZE_Y][TILE_SIZE];
    __shared__ float s_W[TILE_SIZE][BLOCK_SIZE_X];

    int row = blockIdx.y * BLOCK_SIZE_Y + threadIdx.y;
    int col = blockIdx.x * BLOCK_SIZE_X + threadIdx.x;
    int tx = threadIdx.x;
    int ty = threadIdx.y;

    float sum = 0.0f;

    // Loop over K dimension (in_features)
    for (int k = 0; k < in_features; k += TILE_SIZE) {
        // Load tile of x: x[row, k + tx]
        if (row < batch_size && k + tx < in_features) {
            s_x[ty][tx] = x[row * in_features + (k + tx)];
        } else {
            s_x[ty][tx] = 0.0f;
        }

        // Load tile of W: W[col, k + ty]
        // W shape: (out_features, in_features)
        for (int i = ty; i < TILE_SIZE; i += BLOCK_SIZE_Y) {
            if (col < out_features && k + i < in_features) {
                s_W[i][tx] = weight[col * in_features + (k + i)];
            } else {
                s_W[i][tx] = 0.0f;
            }
        }

        __syncthreads();

        // Compute partial sum with unrolled loop
        #pragma unroll 4
        for (int i = 0; i < TILE_SIZE; i++) {
            sum += s_x[ty][i] * s_W[i][tx];
        }

        __syncthreads();
    }

    if (row < batch_size && col < out_features) {
        // Add linear bias
        sum += linear_bias[col];

        // Swish activation: x * sigmoid(x)
        float sigmoid = 1.0f / (1.0f + expf(-sum));
        float swish = sum * sigmoid;

        // Add extra bias
        output[row * out_features + col] = swish + extra_bias[col];
    }
}

torch::Tensor fused_matmul_swish_bias_hip(
    torch::Tensor x,
    torch::Tensor weight,
    torch::Tensor linear_bias,
    torch::Tensor extra_bias) {

    int batch_size = x.size(0);
    int in_features = x.size(1);
    int out_features = weight.size(0);

    auto output = torch::zeros({batch_size, out_features}, x.options());

    dim3 block(BLOCK_SIZE_X, BLOCK_SIZE_Y);
    dim3 grid((out_features + BLOCK_SIZE_X - 1) / BLOCK_SIZE_X, 
              (batch_size + BLOCK_SIZE_Y - 1) / BLOCK_SIZE_Y);

    fused_matmul_swish_bias_kernel<<<grid, block>>>(
        x.data_ptr<float>(),
        weight.data_ptr<float>(),
        linear_bias.data_ptr<float>(),
        extra_bias.data_ptr<float>(),
        output.data_ptr<float>(),
        batch_size,
        in_features,
        out_features);

    return output;
}
"""

