#include <hip/hip_runtime.h>

__device__ float gelu_activation(float x) {
    const float sqrt_2_over_pi = 0.7978845608f;
    const float coeff = 0.044715f;
    return 0.5f * x * (1.0f + tanhf(sqrt_2_over_pi * (x + coeff * x * x * x)));
}

__global__ void gelu_kernel(float* __restrict__ x, int size) {
    const int idx = blockIdx.x * blockDim.x + threadIdx.x;
    if (idx < size) {
        x[idx] = gelu_activation(x[idx]);
    }
}

torch::Tensor gelu(torch::Tensor x) {
    int size = x.numel();
    const int block_size = 1024;
    const int num_blocks = (size + block_size - 1) / block_size;

    gelu_kernel<<<num_blocks, block_size>>>(x.data_ptr<float>(), size);
    return x;
}
"""

# Optimized Softmax kernel with better thread mapping
softmax_cpp = """
#include <hip/hip_runtime.h>
#include <math.h>

__global__ void softmax_kernel(const float* __restrict__ input, float* __restrict__ output, int rows, int cols) {
    int row = blockIdx.x;
    int tid = threadIdx.x;

    if (row >= rows) return;

    const float* row_input = input + row * cols;
    float* row_output = output + row * cols;

    const int grid_size = gridDim.x;
    const int block_size = blockDim.x;
    const int stride = block_size;

    // Compute max in parallel - first pass
    float max_val = -INFINITY;
    for (int i = tid; i < cols; i += stride) {
        max_val = fmaxf(max_val, row_input[i]);
    }

    // Reduce within block
    __shared__ float sdata[1024];
    sdata[tid] = max_val;
    __syncthreads();

    for (int s = block_size / 2; s > 0; s >>= 1) {
        if (tid < s) {
            sdata[tid] = fmaxf(sdata[tid], sdata[tid + s]);
        }
        __syncthreads();
    }

    float block_max = sdata[0];

    // We need a second kernel launch or atomic for global max, but for simplicity
    // we'll use block_max and accept slight numerical differences for now
    __syncthreads();

    // Compute sum of exp(x - max) in parallel
    float sum_exp = 0.0f;
    for (int i = tid; i < cols; i += stride) {
        sum_exp += expf(row_input[i] - block_max);
    }

    // Sum reduction
    sdata[tid] = sum_exp;
    __syncthreads();

    for (int s = block_size / 2; s > 0; s >>= 1) {
        if (tid < s) {
            sdata[tid] += sdata[tid + s];
        }
        __syncthreads();
    }

    float inv_sum = 1.0f / sdata[0];

    // Compute final softmax
    for (int i = tid; i < cols; i += stride) {
        row_output[i] = expf(row_input[i] - block_max) * inv_sum;
    }
}

torch::Tensor softmax(torch::Tensor input) {
    int rows = input.size(0);
    int cols = input.size(1);

    auto output = torch::empty_like(input);

    const int block_size = 1024;
    const int num_blocks = rows;  // One block per row

    softmax_kernel<<<num_blocks, block_size>>>(
        input.data_ptr<float>(), output.data_ptr<float>(), rows, cols);

    return output;
}
"""

