# HIP kernel for fused BatchNorm + Scaling
kernel_code = """
#include <hip/hip_runtime.h>
#include <torch/extension.h>

#define EPSILON 1e-5f

// Fused BatchNorm + Scaling kernel
__global__ void bn_scale_kernel(
    const float* __restrict__ x, 
    const float* __restrict__ mean, 
    const float* __restrict__ var, 
    const float* __restrict__ bn_weight, 
    const float* __restrict__ bn_bias,
    float* __restrict__ out, 
    int N, int C, int H, int W,
    float scaling_factor
) {
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    int total_elements = N * C * H * W;

    if (idx >= total_elements) return;

    // Calculate channel index
    int spatial_size = H * W;
    int tmp = idx;
    int channel = (tmp / spatial_size) % C;

    // Load BN parameters
    float mean_val = mean[channel];
    float var_val = var[channel];
    float weight_val = bn_weight[channel];
    float bias_val = bn_bias[channel];

    // Fused BN + scale calculation
    float inv_std = rsqrtf(var_val + EPSILON);
    float x_val = x[idx];
    float normalized = (x_val - mean_val) * weight_val * inv_std + bias_val;
    float scaled = normalized * scaling_factor;

    // Store result
    out[idx] = scaled;
}

// PyTorch wrapper
torch::Tensor bn_scale_hip(
    torch::Tensor x, torch::Tensor mean, torch::Tensor var, 
    torch::Tensor bn_weight, torch::Tensor bn_bias, 
    float scaling_factor
) {
    // Get dimensions
    int N = x.size(0);
    int C = x.size(1);
    int H = x.size(2);
    int W = x.size(3);

    // Create output tensor
    auto out = torch::zeros_like(x);

    // Calculate grid and block sizes
    int total_elements = x.numel();
    const int block_size = 256;
    const int num_blocks = (total_elements + block_size - 1) / block_size;

    // Launch kernel
    bn_scale_kernel<<<num_blocks, block_size>>>(
        x.data_ptr<float>(),
        mean.data_ptr<float>(),
        var.data_ptr<float>(),
        bn_weight.data_ptr<float>(),
        bn_bias.data_ptr<float>(),
        out.data_ptr<float>(),
        N, C, H, W, 
        scaling_factor
    );

    return out;
}
"""

# Compile the kernel
