    auto output = torch::zeros({batch_size, out_features}, x.options());

    dim3 block(WARP_SIZE * (BLOCK_SIZE_N / 16)); // 64 * 8 = 512 threads
    dim3 grid((out_features + BLOCK_SIZE_N - 1) / BLOCK_SIZE_N, 
