// Add bias and scale kernel
__global__ void bias_scale_kernel(
    const float* __restrict__ x, 
    const float* __restrict__ bias, 
    float* __restrict__ out, 
    float scale,
    int N, int C, int H, int W
) {
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    int total_elements = N * C * H * W;

    if (idx >= total_elements) return;

    // Calculate channel index
    int spatial_size = H * W;
    int channel = (idx / spatial_size) % C;

    // Load bias value and apply
    float bias_val = bias[channel];
    float x_val = x[idx];
    float result = (x_val + bias_val) * scale;

    // Store result
    out[idx] = result;
}

// PyTorch wrapper  
torch::Tensor bias_scale_hip(torch::Tensor x, torch::Tensor bias, float scale) {
    // Get dimensions
    int N = x.size(0);
    int C = x.size(1);
    int H = x.size(2);
    int W = x.size(3);

    // Create output tensor
    auto out = torch::zeros_like(x);

    // Calculate grid and block sizes
    int total_elements = x.numel();
    const int block_size = 256;
    const int num_blocks = (total_elements + block_size - 1) / block_size;

    // Launch kernel
    bias_scale_kernel<<<num_blocks, block_size>>>(
        x.data_ptr<float>(),
        bias.data_ptr<float>(),
        out.data_ptr<float>(),
        scale,
        N, C, H, W
    );

    return out;
}
