)

class ModelNew(nn.Module):
    def __init__(self, in_features, out_features, scaling_factor):
        super(ModelNew, self).__init__()
        self.in_features = in_features
        self.out_features = out_features
        self.scaling_factor = scaling_factor

        # Initialize weight and bias (same as nn.Linear)
        self.weight = nn.Parameter(torch.randn(out_features, in_features))
        self.bias = nn.Parameter(torch.randn(out_features))

        self.fused_kernel = fused_kernel

    def forward(self, x):
        # Extract weight.t() to match PyTorch's Linear convention
        # PyTorch Linear: x @ weight.t() + bias
        # We treat weight.t() as [in_features, out_features] where K=in_features, N=out_features
        weight_t = self.weight.t().contiguous()

        # Fused GEMM + Swish + Scaling
        return self.fused_kernel.fused_gemm_swish_scale_hip(
            x, weight_t, self.bias, self.scaling_factor
        )

