    dim3 block_size(TILE_WIDTH, TILE_HEIGHT);
    dim3 grid_size(
        (out_width + TILE_WIDTH - 1) / TILE_WIDTH,
        (out_height + TILE_HEIGHT - 1) / TILE_HEIGHT,
        out_channels,
