#define EPSILON 1e-5f
#define TILE_WIDTH 32

// Kernel constants for performance
#define C_IN 8    // Fixed input channels
#define K_SIZE 3  // Fixed kernel size

// Tiled convolution with fused BatchNorm and scaling
__global__ void optimized_conv_bn_scale(
    const float* __restrict__ input,   // [N, C_in, H, W]
    const float* __restrict__ weight,  // [C_out, C_in, K_h, K_w]
    const float* __restrict__ bias,    // [C_out]
    const float* __restrict__ bn_mean,  // [C_out]
    const float* __restrict__ bn_var,   // [C_out]
    const float* __restrict__ bn_weight, // [C_out]
    const float* __restrict__ bn_bias,   // [C_out]
    float* __restrict__ output,         // [N, C_out, H_out, W_out]
    int N, int C_out, int H, int W, int H_out, int W_out,
    float scaling_factor
) {
    // Each block processes one output channel
    int c_out = blockIdx.x;

    // Handle multiple batches per block
    int n = blockIdx.y;

    // Thread position in output
    int h_out = threadIdx.x;
    int w_out = threadIdx.y;

    // Bounds check
    if (c_out >= C_out || n >= N || h_out >= H_out || w_out >= W_out) return;

    // Precompute BN parameters with scaling
    float inv_std = rsqrtf(bn_var[c_out] + EPSILON);
    float bn_scale = bn_weight[c_out] * inv_std;
    float bn_offset = bn_bias[c_out] - bn_mean[c_out] * bn_weight[c_out] * inv_std;

    // Add conv bias if it exists
    if (bias != nullptr) {
        bn_offset += bias[c_out] * bn_scale;
    }

    // Apply final scaling to both BN scale and offset
    bn_scale *= scaling_factor;
    bn_offset *= scaling_factor;

    // Compute convolution - unrolled loops for performance
    float sum = 0.0f;

    // Fixed loops for better optimization
    #pragma unroll C_IN
    for (int c_in = 0; c_in < C_IN; ++c_in) {
        const float* input_ptr = input + ((n * C_IN + c_in) * H) * W;
        const float* weight_ptr = weight + ((c_out * C_IN + c_in) * K_SIZE) * K_SIZE;

        int h_in_base = h_out;
        int w_in_base = w_out;

        #pragma unroll K_SIZE
        for (int kh = 0; kh < K_SIZE; ++kh) {
            int h_index = h_in_base + kh;

            #pragma unroll K_SIZE
            for (int kw = 0; kw < K_SIZE; ++kw) {
                int w_index = w_in_base + kw;

                // Load input and weight (coalesced access)
                float input_val = input_ptr[h_index * W + w_index];
                float weight_val = weight_ptr[kh * K_SIZE + kw];

                sum += input_val * weight_val;
            }
        }
    }

    // Apply BN and scaling
    float result = sum * bn_scale + bn_offset;

    // Write output (coalesced access)
    output[((n * C_out + c_out) * H_out + h_out) * W_out + w_out] = result;
}

// PyTorch wrapper
torch::Tensor fused_conv_bn_scale_hip(
    torch::Tensor input,
    torch::Tensor weight,
    torch::Tensor bias,
    torch::Tensor bn_mean,
    torch::Tensor bn_var,
    torch::Tensor bn_weight,
    torch::Tensor bn_bias,
    float scaling_factor
) {
    // Extract dimensions
    int N = input.size(0);
    int C_in = input.size(1);
    int H = input.size(2);
    int W = input.size(3);
    int C_out = weight.size(0);
    int K_h = weight.size(2);
    int K_w = weight.size(3);

    // Calculate output dimensions (no padding)
    int H_out = H - K_h + 1;
    int W_out = W - K_w + 1;

    // Create output tensor
    auto output = torch::zeros({N, C_out, H_out, W_out}, input.options());

    // Grid dimension: (output_channels x batch)
    dim3 grid_size(C_out, N);
    dim3 block_size(H_out, W_out);

    // Launch kernel with a 2D thread block
    optimized_conv_bn_scale<<<grid_size, block_size>>>(
        input.data_ptr<float>(),
        weight.data_ptr<float>(),
        bias.defined() ? bias.data_ptr<float>() : nullptr,
        bn_mean.data_ptr<float>(),
        bn_var.data_ptr<float>(),
        bn_weight.data_ptr<float>(),
        bn_bias.data_ptr<float>(),
        output.data_ptr<float>(),
        N, C_out, H, W, H_out, W_out,
        scaling_factor
    );

    return output;
}
"""

