fused_gemm_gelu_cpp = """
#include <hip/hip_runtime.h>
#include <hipblas/hipblas.h>

torch::Tensor fused_gemm_gelu(torch::Tensor x, torch::Tensor weight, torch::Tensor bias) {
    int batch_size = x.size(0);
    int in_features = x.size(1);
    int out_features = weight.size(0);

    auto output = torch::empty({batch_size, out_features}, x.options());

    // Use hipblas for matmul (already optimized)
    // Then apply GELU manually
    torch::Tensor temp = torch::addmm(bias.unsqueeze(0).expand({batch_size, out_features}), x, weight.t());

    // In-place GELU
    float* data = temp.data_ptr<float>();
    const float sqrt_2_over_pi = 0.7978845608f;
    const float coeff = 0.044715f;

    #pragma omp parallel for
    for (int i = 0; i < batch_size * out_features; i++) {
        float x_val = data[i];
        float gelu = 0.5f * x_val * (1.0f + std::tanh(sqrt_2_over_pi * (x_val + coeff * x_val * x_val * x_val)));
        data[i] = gelu;
    }

    return temp;
}
"""

# Optimized Softmax kernel - fixed version
softmax_cpp = """
#include <hip/hip_runtime.h>
#include <math.h>
#include <float.h>

__global__ void softmax_kernel(const float* __restrict__ input, float* __restrict__ output, int rows, int cols) {
    int row = blockIdx.x;
    int tid = threadIdx.x;

    if (row >= rows) return;

    const float* row_input = input + row * cols;
    float* row_output = output + row * cols;

    __shared__ float shared_data[1024];

    // Find max value
    float max_val = -FLT_MAX;
    for (int i = tid; i < cols; i += blockDim.x) {
        float val = (i < cols) ? row_input[i] : -FLT_MAX;
        max_val = fmaxf(max_val, val);
    }
    shared_data[tid] = max_val;
    __syncthreads();

    // Reduce max
    for (int stride = blockDim.x / 2; stride > 0; stride >>= 1) {
        if (tid < stride) {
            shared_data[tid] = fmaxf(shared_data[tid], shared_data[tid + stride]);
        }
        __syncthreads();
    }

    float max_val_all = shared_data[0];
    __syncthreads();

    // Compute exp sum
    float sum_exp = 0.0f;
    for (int i = tid; i < cols; i += blockDim.x) {
        if (i < cols) {
            sum_exp += expf(row_input[i] - max_val_all);
        }
    }
    shared_data[tid] = sum_exp;
    __syncthreads();

    // Reduce sum
    for (int stride = blockDim.x / 2; stride > 0; stride >>= 1) {
        if (tid < stride) {
            shared_data[tid] += shared_data[tid + stride];
        }
        __syncthreads();
    }

    float sum_exp_all = shared_data[0];
    __syncthreads();

    // Compute softmax values
    for (int i = tid; i < cols; i += blockDim.x) {
        if (i < cols) {
            row_output[i] = expf(row_input[i] - max_val_all) / sum_exp_all;
        }
    }
}

torch::Tensor softmax(torch::Tensor input) {
    int rows = input.size(0);
    int cols = input.size(1);

    auto output = torch::zeros_like(input);

    const int block_size = 256;
    const int num_blocks = rows;

    softmax_kernel<<<num_blocks, block_size>>>(
        input.data_ptr<float>(), output.data_ptr<float>(), rows, cols);

    return output;
}
"""

