# Define the combined HIP kernel source code
hip_source = """
#include <hip/hip_runtime.h>
#include <math.h>

#define BLOCK_SIZE 8

// Simplified Conv2d with bias kernel
__global__ void conv2d_bias_kernel(
    const float* __restrict__ input,
    const float* __restrict__ weight,
    const float* __restrict__ bias,
    float* __restrict__ output,
    int batch_size, int in_channels, int out_channels,
    int height, int width, int kernel_size,
    int out_height, int out_width
) {
    int b = blockIdx.x;
    int oc = blockIdx.y;
    int h = blockIdx.z * BLOCK_SIZE + threadIdx.x;
    int w = threadIdx.y;

    if (b >= batch_size || oc >= out_channels || h >= out_height || w >= out_width) return;

    float sum = bias[oc];  // Initialize with bias value

    // Compute convolution - simpler indexing
    for (int ic = 0; ic < in_channels; ++ic) {
        for (int kh = 0; kh < kernel_size; ++kh) {
            int ih = h + kh;
            for (int kw = 0; kw < kernel_size; ++kw) {
                int iw = w + kw;

                float input_val = input[((b * in_channels + ic) * height + ih) * width + iw];
                float weight_val = weight[((oc * in_channels + ic) * kernel_size + kh) * kernel_size + kw];
                sum += input_val * weight_val;
            }
        }
    }

    output[((b * out_channels + oc) * out_height + h) * out_width + w] = sum;
}

// InstanceNorm + Div kernel using more efficient parallel reduction
__global__ void instancenorm_div_kernel(
    float* __restrict__ output,
    const float* __restrict__ input,
    int batch_size, int channels, int height, int width,
    float eps, float divide_by
) {
    __shared__ float sdata[256];

    int batch_idx = blockIdx.x;
    int channel_idx = blockIdx.y;
    int tid = threadIdx.x;
    int num_elements = height * width;

    if (batch_idx >= batch_size || channel_idx >= channels) return;

    // Step 1: Compute mean
    float sum = 0.0f;
    for (int i = tid; i < num_elements; i += blockDim.x) {
        int h = i / width;
        int w = i % width;
        sum += input[((batch_idx * channels + channel_idx) * height + h) * width + w];
    }

    // Reduction to compute total sum
    sdata[tid] = sum;
    __syncthreads();

    for (int s = blockDim.x / 2; s > 0; s >>= 1) {
        if (tid < s) {
            sdata[tid] += sdata[tid + s];
        }
        __syncthreads();
    }

    float mean = sdata[0] / num_elements;

    // Step 2: Compute variance
    __syncthreads();
    float sum_sq = 0.0f;
    for (int i = tid; i < num_elements; i += blockDim.x) {
        int h = i / width;
        int w = i % width;
        float val = input[((batch_idx * channels + channel_idx) * height + h) * width + w];
        float diff = val - mean;
        sum_sq += diff * diff;
    }

    // Reduction for sum of squares
    sdata[tid] = sum_sq;
    __syncthreads();

    for (int s = blockDim.x / 2; s > 0; s >>= 1) {
        if (tid < s) {
            sdata[tid] += sdata[tid + s];
        }
        __syncthreads();
    }

    float var = sdata[0] / num_elements;

    // Step 3: Apply normalization and division - compute in normalized space
    float inv_std = rsqrtf(var + eps);
    for (int i = tid; i < num_elements; i += blockDim.x) {
        int h = i / width;
        int w = i % width;
        float val = input[((batch_idx * channels + channel_idx) * height + h) * width + w];
        output[((batch_idx * channels + channel_idx) * height + h) * width + w] = 
            ((val - mean) * inv_std) / divide_by;
    }
}

// Wrapper functions

// Conv2d wrapper
torch::Tensor conv2d_bias_hip(torch::Tensor input, torch::Tensor weight, torch::Tensor bias) {
    auto batch_size = input.size(0);
    auto in_channels = input.size(1);
    auto height = input.size(2);
    auto width = input.size(3);

    auto out_channels = weight.size(0);
    auto kernel_size = weight.size(2);

    // Output dimensions for convolution with stride=1, padding=0
    int out_height = height - kernel_size + 1;
    int out_width = width - kernel_size + 1;

    auto output = torch::zeros({batch_size, out_channels, out_height, out_width}, 
                               torch::dtype(torch::kFloat32).device(torch::kCUDA));

    // Launch kernel with 3D grid for better occupancy
    int tile_h = (out_height + BLOCK_SIZE - 1) / BLOCK_SIZE;
    dim3 grid(batch_size, out_channels, tile_h);
    dim3 block(BLOCK_SIZE, 1, 1);

    conv2d_bias_kernel<<<grid, block>>>(
        input.data_ptr<float>(), weight.data_ptr<float>(), bias.data_ptr<float>(), output.data_ptr<float>(),
        batch_size, in_channels, out_channels, height, width, kernel_size, out_height, out_width
    );

    return output;
}

// InstanceNorm + Div wrapper
torch::Tensor instancenorm_div_hip(torch::Tensor input, float eps, float divide_by) {
    auto batch_size = input.size(0);
    auto channels = input.size(1);
    auto height = input.size(2);
    auto width = input.size(3);

    dim3 block(256);  // 256 threads per block
    dim3 grid(batch_size, channels);

    // Create output tensor (don't modify input in-place)
    auto output = torch::zeros_like(input);

    instancenorm_div_kernel<<<grid, block>>>(
        output.data_ptr<float>(),
        input.data_ptr<float>(),
        batch_size, channels, height, width, eps, divide_by
    );

    return output;
}
"""

# Compile the HIP kernels
conv_instancenorm_div = load_inline(
    name='conv_instancenorm_div_v2',
    cpp_sources=hip_source,
