# Optimized HIP kernel for Conv2D + BN + Scaling
kernel_code = """
#include <hip/hip_runtime.h>
#include <torch/extension.h>

#define EPSILON 1e-5f
#define BLOCK_SIZE 256

// Fused Conv2D + BatchNorm + Scaling kernel with optimized memory access
__global__ void fused_conv_bn_scale_kernel(
    const float* __restrict__ input,   // [N, C_in, H, W]
    const float* __restrict__ weight,  // [C_out, C_in, K_h, K_w]
    const float* __restrict__ bias,    // [C_out]
    const float* __restrict__ bn_mean,  // [C_out]
    const float* __restrict__ bn_var,   // [C_out]
    const float* __restrict__ bn_weight, // [C_out]
    const float* __restrict__ bn_bias,   // [C_out]
    float* __restrict__ output,         // [N, C_out, H_out, W_out]
    int N, int C_in, int H, int W,
    int C_out, int H_out, int W_out,
    float scaling_factor
) {
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    int total_elements = N * C_out * H_out * W_out;

    if (idx >= total_elements) return;

    // Decompose index: (n, c_out, h_out, w_out)
    int tmp = idx;
    int w_out = tmp % W_out;
    tmp /= W_out;
    int h_out = tmp % H_out;
    tmp /= H_out;
    int c_out = tmp % C_out;
    int n = tmp / C_out;

    // Precompute BN + scale + bias parameters
    float inv_std = rsqrtf(bn_var[c_out] + EPSILON);
    float bn_scale = bn_weight[c_out] * inv_std;
    float bn_offset = bn_bias[c_out] - bn_mean[c_out] * bn_weight[c_out] * inv_std;

    // Add conv bias
    if (bias != nullptr) {
        bn_offset += bias[c_out] * bn_scale;
    }

    // Apply scaling factor
    bn_scale *= scaling_factor;
    bn_offset *= scaling_factor;

    // Compute convolution
    float sum = 0.0f;

    // Loop over input channels (C_in = 8, small and fixed)
    // This enables compiler unrolling and register optimization
    const int K_h = 3;
    const int K_w = 3;

    for (int c_in = 0; c_in < C_in; ++c_in) {
        // Calculate base pointers for this channel
        const float* input_row = input + n * (C_in * H * W) + c_in * (H * W) + h_out * W;
        const float* weight_col = weight + c_out * (C_in * K_h * K_w) + c_in * (K_h * K_w);

        // Unroll the kernel loops
        sum += input_row[w_out + 0] * weight_col[0];      // kh=0, kw=0
        sum += input_row[w_out + 1] * weight_col[1];      // kh=0, kw=1
        sum += input_row[w_out + 2] * weight_col[2];      // kh=0, kw=2

        input_row += W;  // Move to next row
        weight_col += K_w;

        sum += input_row[w_out + 0] * weight_col[0];      // kh=1, kw=0
        sum += input_row[w_out + 1] * weight_col[1];      // kh=1, kw=1
        sum += input_row[w_out + 2] * weight_col[2];      // kh=1, kw=2

        input_row += W;  // Move to next row
        weight_col += K_w;

        sum += input_row[w_out + 0] * weight_col[0];      // kh=2, kw=0
        sum += input_row[w_out + 1] * weight_col[1];      // kh=2, kw=1
        sum += input_row[w_out + 2] * weight_col[2];      // kh=2, kw=2
    }

    // Apply BN + bias + scaling
    float result = sum * bn_scale + bn_offset;

    // Write output (coalesced access)
    output[idx] = result;
}

// Launch wrapper
torch::Tensor fused_conv_bn_scale_hip(
    torch::Tensor input,
    torch::Tensor weight,
    torch::Tensor bias,
    torch::Tensor bn_mean,
    torch::Tensor bn_var,
    torch::Tensor bn_weight,
    torch::Tensor bn_bias,
    float scaling_factor
) {
    // Extract dimensions
    int N = input.size(0);
    int C_in = input.size(1);
    int H = input.size(2);
    int W = input.size(3);
    int C_out = weight.size(0);
    int K_h = weight.size(2);
    int K_w = weight.size(3);

    // Calculate output dimensions (no padding)
    int H_out = H - K_h + 1;  // 128 - 3 + 1 = 126
    int W_out = W - K_w + 1;  // 128 - 3 + 1 = 126

    // Create output tensor
    auto output = torch::zeros({N, C_out, H_out, W_out}, input.options());

    // Calculate grid dimensions - 1D grid for better occupancy
    int total_elements = N * C_out * H_out * W_out;
    int num_blocks = (total_elements + BLOCK_SIZE - 1) / BLOCK_SIZE;

    // Launch kernel
    fused_conv_bn_scale_kernel<<<num_blocks, BLOCK_SIZE>>>(
        input.data_ptr<float>(),
        weight.data_ptr<float>(),
        bias.defined() ? bias.data_ptr<float>() : nullptr,
        bn_mean.data_ptr<float>(),
        bn_var.data_ptr<float>(),
        bn_weight.data_ptr<float>(),
        bn_bias.data_ptr<float>(),
        output.data_ptr<float>(),
        N, C_in, H, W,
        C_out, H_out, W_out,
        scaling_factor
    );

    return output;
}
"""

