// Helper function for GELU
__device__ float gelu_func(float x) {
    const float sqrt_2_over_pi = 0.7978845608f;
    const float coeff = 0.044715f;
    return 0.5f * x * (1.0f + tanhf(sqrt_2_over_pi * (x + coeff * x * x * x)));
}

// Simple kernel for bias add + GELU
__global__ void bias_gelu_kernel(float* __restrict__ x, const float* __restrict__ bias, int n, int cols) {
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    if (idx < n) {
        int col = idx % cols;
        x[idx] = gelu_func(x[idx] + bias[col]);
    }
}

// Main fused operation
void fused_linear_gelu(torch::Tensor x, torch::Tensor weight, torch::Tensor bias, torch::Tensor output) {
    int batch_size = x.size(0);
    int in_features = x.size(1);
    int out_features = weight.size(0);

    // Use hipblas for matmul (this is already optimized)
    // Then fuse bias add + GELU in a separate kernel

    float alpha = 1.0f, beta = 0.0f;
    auto handle = get_cublas_handle();

    hipblasSgemm(handle, HIPBLAS_OP_N, HIPBLAS_OP_T, 
                 out_features, batch_size, in_features,
                 &alpha, weight.data_ptr<float>(), out_features,
                 x.data_ptr<float>(), in_features,
                 &beta, output.data_ptr<float>(), out_features);

    // Launch fusion kernel
    int total_elements = batch_size * out_features;
    const int block_size = 256;
    const int num_blocks = (total_elements + block_size - 1) / block_size;

    bias_gelu_kernel<<<num_blocks, block_size>>>(
        output.data_ptr<float>(), 
        bias.data_ptr<float>(), 
        total_elements, 
