    int oc = blockIdx.y;
    int oh = blockIdx.z * BLOCK_SIZE + threadIdx.x;
    int ow = threadIdx.y;

    if (b >= batch_size || oc >= out_channels || oh >= out_height || ow >= out_width) return;

    float sum = bias[oc];  // Initialize with bias

    // Compute convolution with optimized memory access
    for (int ic = 0; ic < in_channels; ++ic) {
        int input_channel_offset = (b * in_channels + ic) * height * width;
        int weight_channel_offset = (oc * in_channels + ic) * kernel_size * kernel_size;

        for (int kh = 0; kh < kernel_size; ++kh) {
            int ih = oh + kh;
            int input_h_offset = input_channel_offset + ih * width;
            int weight_h_offset = weight_channel_offset + kh * kernel_size;

            for (int kw = 0; kw < kernel_size; ++kw) {
                int iw = ow + kw;

                float input_val = input[input_h_offset + iw];
                float weight_val = weight[weight_h_offset + kw];
                sum += input_val * weight_val;
            }
        }
    }

    int output_offset = ((b * out_channels + oc) * out_height + oh) * out_width + ow;
    output[output_offset] = sum;
}

// InstanceNorm + Div kernel - FIXED version
__global__ void instancenorm_div_kernel(
    float* __restrict__ output,
    const float* __restrict__ input,
    int batch_size, int channels, int height, int width,
    float eps, float divide_by
) {
    __shared__ float sdata[256];

    int b = blockIdx.x;
    int c = blockIdx.y;
    int tid = threadIdx.x;
    int num_elements = height * width;

    if (b >= batch_size || c >= channels) return;

    int offset = (b * channels + c) * height * width;

    // Compute mean
    float sum = 0.0f;
    for (int i = tid; i < num_elements; i += blockDim.x) {
        sum += input[offset + i];
    }

    sdata[tid] = sum;
    __syncthreads();

    for (int s = blockDim.x / 2; s > 0; s >>= 1) {
        if (tid < s) {
            sdata[tid] += sdata[tid + s];
        }
        __syncthreads();
    }

    float mean = sdata[0] / num_elements;

    // Compute variance
    __syncthreads();
    float sum_sq = 0.0f;
    for (int i = tid; i < num_elements; i += blockDim.x) {
        float diff = input[offset + i] - mean;
        sum_sq += diff * diff;
    }

    sdata[tid] = sum_sq;
    __syncthreads();

    for (int s = blockDim.x / 2; s > 0; s >>= 1) {
        if (tid < s) {
            sdata[tid] += sdata[tid + s];
        }
        __syncthreads();
    }

    float var = sdata[0] / num_elements;
    float inv_std_rsqrt = rsqrtf(var + eps);

    // Apply normalization and division
    for (int i = tid; i < num_elements; i += blockDim.x) {
        output[offset + i] = ((input[offset + i] - mean) * inv_std_rsqrt) / divide_by;
    }
}

